<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';
require_once __DIR__.'/config/final_launch_step25.php';
$error=null;$notice=null;$state=[];$user=[];
try{
    $pdo=business_db();$user=security_step17_current_user($pdo);if(!security_step17_has_permission($pdo,'deployment.view',$user))throw new RuntimeException('Deployment View permission is required.');
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));
        step25_record_uat($pdo,$user,(array)($_POST['uat']??[]),(string)($_POST['notes']??''));
        $notice='STEP 25 UAT sign-off recorded in the deployment audit trail.';
    }
    $state=step25_state($pdo);
}catch(Throwable $e){$error=$e->getMessage();}
$env=strtoupper((string)($state['runtime']['environment']??'local'));
$canSign=$error===null&&isset($pdo)&&($state['runtime']['environment']??'local')==='production'&&security_step17_has_permission($pdo,'deployment.release',$user);
$headline=!empty($state['production_live'])?'PRODUCTION RELEASE IS RECORDED LIVE':(!empty($state['production_ready'])?'READY FOR PRODUCTION RELEASE':(!empty($state['core_ready'])?'FINAL QA READY — COMPLETE UAT / SERVER GATES':'FINAL QA NEEDS REVIEW'));
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Final Launch Center - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="index.php"><img src="../img/logo.png" alt="Healthcare Wellness Club"><span><strong>Healthcare Wellness Club</strong><small>STEP 25 • Final QA/UAT + Production Launch</small></span></a><div class="os-top-actions"><a class="os-btn" href="step25_audit.php">Automated QA</a><a class="os-btn" href="production_health.php">Production Health</a><a class="os-btn primary" href="deployment_releases.php">Releases</a></div></div></header><main class="os-main" style="max-width:1540px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">FINAL LAUNCH CONTROL</div><h1><?=step25_h($headline)?></h1><p>This page combines final regression evidence, human UAT, recovery readiness and the existing STEP 19 production gates. It never marks a release live merely because local tests passed.</p><div class="os-status-row"><span class="os-chip good"><?=step25_h($env)?></span><span class="os-chip <?=!empty($state['core_ready'])?'good':''?>"><?=!empty($state['core_ready'])?'CORE QA PASS':'CORE QA REVIEW'?></span><span class="os-chip <?=!empty($state['latest_uat'])?'good':''?>"><?=!empty($state['latest_uat'])?'UAT SIGNED':'UAT PENDING'?></span><span class="os-chip <?=!empty($state['production_live'])?'good':''?>"><?=!empty($state['production_live'])?'LIVE RECORDED':'NOT MARKED LIVE'?></span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Launch diagnostic:</strong> <?=step25_h($error)?></div><?php endif;?><?php if($notice):?><div class="pp-alert good"><?=step25_h($notice)?></div><?php endif;?><?php if(!$error):?><section class="s10-grid"><article class="s10-card s10-span-7"><div class="os-title-row"><div><h2>Production Gates</h2><p>Production-only server values stay outside Git. A local machine is allowed to show these as pending.</p></div><span class="pp-badge <?=!empty($state['production_ready'])?'':'warn'?>"><?=!empty($state['production_ready'])?'READY':'PENDING'?></span></div><div class="s10-checks"><?php foreach($state['production_gates'] as$g):?><div class="s10-check <?=$g['ok']?'good':'warn'?>"><div><b><?=step25_h($g['name'])?></b><span><?=step25_h($g['detail'])?></span></div><strong><?=$g['ok']?'PASS':'REVIEW'?></strong></div><?php endforeach;?></div><div class="pp-alert" style="margin-top:12px"><strong>Rule:</strong> Only the existing Deployment Releases workflow may record a production release as <code>deployed</code>. STEP 25 UAT does not bypass that control.</div></article><aside class="s10-card s10-span-5"><h2>Current Evidence</h2><div class="s10-list"><div class="s10-row"><div><b>Legacy workbook</b><small><?= (int)($state['legacy']['mapped_rows']??0) ?> / 757 mapped • <?= (int)($state['legacy']['pending_rows']??0) ?> pending</small></div></div><div class="s10-row"><div><b>Product catalog</b><small><?= (int)$state['products'] ?> active • <?= (int)$state['catalog'] ?> public</small></div></div><div class="s10-row"><div><b>Verified backups</b><small><?= (int)$state['verified_backups'] ?> current recovery point(s)</small></div></div><div class="s10-row"><div><b>Invalid public orders</b><small><?= (int)$state['invalid_orders'] ?> structural issue(s)</small></div></div><div class="s10-row"><div><b>Latest release</b><small><?=step25_h($state['latest_release']?($state['latest_release']['version_label'].' • '.$state['latest_release']['release_status']):'none registered')?></small></div></div></div></aside></section><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Human UAT Sign-off</h2><p>Run these on the target browser/device/server. Check a case only after the expected result is actually observed.</p></div><span class="pp-badge <?=!empty($state['latest_uat'])?'':'warn'?>"><?=!empty($state['latest_uat'])?'SIGNED':'10 CASES'?></span></div><?php if(!empty($state['latest_uat'])):?><div class="pp-alert good">Latest UAT sign-off: <?=step25_h($state['latest_uat']['created_at'])?>. You may run and record a newer sign-off after any release change.</div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=step25_h(security_step17_csrf())?>"><div class="pp-grid"><?php foreach(step25_uat_catalog() as$case):?><label class="pp-source pp-span-6" style="align-items:flex-start;cursor:pointer"><input type="checkbox" name="uat[]" value="<?=step25_h($case['id'])?>" style="margin-top:4px"><div><b><?=step25_h($case['name'])?></b><small><strong>Test:</strong> <?=step25_h($case['test'])?><br><strong>Expected:</strong> <?=step25_h($case['expect'])?></small></div></label><?php endforeach;?></div><label style="display:block;margin-top:14px"><b>UAT note (optional)</b><textarea class="pp-input" name="notes" rows="3" maxlength="2000" style="width:100%;margin-top:6px" placeholder="Device/browser/server notes; never paste passwords or tokens here."></textarea></label><button class="os-btn primary" style="margin-top:12px" <?=$canSign?'':'disabled'?>>Record Complete UAT Sign-off</button><?php if(!$canSign):?><span class="os-chip" style="margin-left:8px"><?=($state['runtime']['environment']??'local')!=='production'?'production environment required':'deployment.release permission required'?></span><?php endif;?></form></section><section class="os-card" style="margin-top:14px"><h2>Go-Live Sequence</h2><div class="s10-list"><div class="s10-row"><div><b>1. Automated QA</b><small>STEP 25 audit must show zero automated regression reviews.</small></div><a class="s10-link" href="step25_audit.php">Audit →</a></div><div class="s10-row"><div><b>2. Verified Backup</b><small>Create/verify the final pre-release recovery point.</small></div><a class="s10-link" href="backup_center.php">Backup →</a></div><div class="s10-row"><div><b>3. Target Server Health</b><small>Production environment, HTTPS, host allowlist and dedicated DB credentials.</small></div><a class="s10-link" href="production_health.php">Health →</a></div><div class="s10-row"><div><b>4. Human UAT</b><small>Complete the 10 cases above and record sign-off.</small></div><span class="s10-badge <?=!empty($state['latest_uat'])?'':'warn'?>"><?=!empty($state['latest_uat'])?'DONE':'PENDING'?></span></div><div class="s10-row"><div><b>5. Release Record</b><small>Record exact production version/Git SHA as deployed only after all gates pass.</small></div><a class="s10-link" href="deployment_releases.php">Release →</a></div></div></section><?php endif;?></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
